    "task_id",
        "created_at",
        "requested_by",
        "source_channel",
        "priority",
        "objective",
        "allowed_scope",
        "deferred_gates",
        "target_runner",
        "tmux_session",
        "workspace_path",
        "validation_commands",
        "expected_artifacts",
        "status",
        "retry_count",
        "max_retries",
