            "type": "string"
        },
        "last_heartbeat_at": {
            "type": [
                "string",
                "null"
            ]
        },
        "last_log_path": {
            "type": [
                "string",
                "null"
            ]
        },
        "last_validation_result": {
            "type": "object",
            "additionalProperties": false,
            "required": [
                "status",
                "command",
                "checked_at"
            ],
            "properties": {
                "status": {
                    "type": "string",
                    "enum": [
                        "PASS",
                        "FAIL",
                        "NOT_RUN",
                        "DEFERRED_GATE"
                    ]
                },
                "command": {
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "checked_at": {
                    "type": [
                        "string",
                        "null"
                    ]
                }
            }
        },
        "blocked_gates": {
            "type": "array",
            "items": {
                "type": "object",
                "additionalProperties": false,
                "required": [
                    "name",
                    "status",
                    "reason"
                ],
                "properties": {
                    "name": {
                        "type": "string"
                    },
                    "status": {
                        "type": "string",
                        "const": "DEFERRED_GATE"
                    },
                    "reason": {
                        "type": "string"
                    }
                }
            }
        },
        "safe_next_actions": {
            "type": "array",
            "items": {
                "type": "string"
            }
        },
        "kill_switch_status": {
            "type": "object",
            "additionalProperties": false,
            "required": [
                "enabled",
                "last_triggered_at",
                "command"
            ],
            "properties": {
                "enabled": {
                    "type": "boolean"
                },
                "last_triggered_at": {
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "command": {
                    "type": "string"
                }
            }
        }
    }
}

